import json,hashlib
def replay(lines):
 result={};expected=1
 for line in lines:
  row=json.loads(line);payload=row['payload']
  raw=json.dumps(payload,sort_keys=True,separators=(',',':')).encode()
  if row['seq']!=expected or row['sha256']!=hashlib.sha256(raw).hexdigest():raise ValueError('corrupt')
  if payload['op']=='set':result[payload['key']]=payload['value']
  elif payload['op']=='delete':result.pop(payload['key'],None)
  else:raise ValueError('operation')
  expected+=1
 return result

