import argparse,json,sys
from pathlib import Path
import task

def main():
 p=argparse.ArgumentParser()
 p.add_argument('--input',required=True)
 p.add_argument('--capacity',required=True,type=int)
 p.add_argument('--ttl',required=True,type=float)
 args=p.parse_args();cache=task.TTLCache(args.capacity,args.ttl);result=[]
 with open(args.input,encoding='utf-8') as source:
  for line in source:
   event=json.loads(line);op=event['op'];key=event['key'];now=event['time']
   if op=='put':cache.put(key,event['value'],now);result.append({'status':'stored'})
   elif op=='get':
    try:result.append({'status':'hit','value':cache.get(key,now)})
    except KeyError:result.append({'status':'miss'})
   else:raise ValueError('unknown operation')
 print(json.dumps(result,ensure_ascii=False))

if __name__=='__main__':
 try:main()
 except (ValueError,KeyError,TypeError,OSError) as error:
  print(type(error).__name__+': '+str(error),file=sys.stderr)
  sys.exit(2)

