def audit(roles,bindings,requests):
 memo={};visiting=set()
 def expand(name):
  if name not in roles:raise ValueError('unknown role')
  if name in visiting:raise ValueError('role cycle')
  if name in memo:return memo[name]
  visiting.add(name);role=roles[name];allow=set(map(tuple,role.get('allow',[])));deny=set(map(tuple,role.get('deny',[])))
  for parent in role.get('inherits',[]):
   a,d=expand(parent);allow|=a;deny|=d
  visiting.remove(name);memo[name]=(allow,deny);return memo[name]
 for name in roles:expand(name)
 for b in bindings:
  if b['role']not in roles:raise ValueError('unknown binding')
 def matches(rule,verb,resource):
  return rule[0]in ('*',verb)and rule[1]in ('*',resource)
