  allow=set();deny=set()
  for b in bindings:
   if b['user']==user and b['namespace']in ('*',namespace):
    a,d=memo[b['role']];allow|=a;deny|=d
  results.append(any(matches(r,verb,resource)for r in allow)and not any(matches(r,verb,resource)for r in deny))
 return results

